// Importing album art library
const albumArt = require('album-art');

// Importing movie art library
const movieArt = require('movie-art'); // Assuming there's a movie-art package similar to album-art

// Function to encode special characters in the search query
const encodeQuery = (query) => {
  return query.replace(/&/g, '%26'); // Encode the "&" character
};

export default function VibeSuggester() {
  const [suggestions, setSuggestions] = useState({
    song: getRandomItem(songs, null),
    movie: getRandomItem(movies, null),
    weed: getRandomItem(weeds, null),
    food: getRandomItem(foods, null),
  });

  const [shake, setShake] = useState(false);
  const [songCover, setSongCover] = useState('');
  const [movieCover, setMovieCover] = useState('');  // New state for movie cover

  useEffect(() => {
    // Fetch album art for the initial song
    fetchAlbumArt(suggestions.song.artist, suggestions.song.song);

    // Fetch movie art for the initial movie
    fetchMovieArt(suggestions.movie.name);

    // Add event listener for the spacebar
    const handleSpacebarPress = (event) => {
      if (event.code === 'Space') {  // Check if spacebar is pressed
        event.preventDefault(); // Prevent the default spacebar behavior (scrolling the page)
        randomize(); // Trigger the randomize function
      }
    };

    // Attach event listener for spacebar
    document.addEventListener('keydown', handleSpacebarPress);

    // Cleanup the event listener on component unmount
    return () => {
      document.removeEventListener('keydown', handleSpacebarPress);
    };
  }, [suggestions.song, suggestions.movie]);

  const fetchAlbumArt = async (artist, song) => {
    try {
      const cover = await albumArt(artist, { album: song });
      setSongCover(cover);
    } catch (error) {
      console.error("Error fetching album art:", error);
      setSongCover('https://default_image_url.jpg'); // Default image URL if fetching fails
    }
  };

  const fetchMovieArt = async (movieName) => {
    try {
      const cover = await movieArt(movieName);  // Fetch movie art by name
      setMovieCover(cover);
    } catch (error) {
      console.error("Error fetching movie art:", error);
      setMovieCover('https://default_image_url.jpg'); // Default image URL if fetching fails
    }
  };

  const randomize = () => {
    setShake(true);
    setSuggestions((prev) => ({
      song: getRandomItem(songs, prev.song),
      movie: getRandomItem(movies, prev.movie),
      weed: getRandomItem(weeds, prev.weed),
      food: getRandomItem(foods, prev.food),
    }));

    // Reset the shake animation after it finishes
    setTimeout(() => setShake(false), 500); // 500ms to match the animation duration
  };

  const handleSongClick = (songName) => {
    const encodedSongName = encodeQuery(songName);
    const youtubeUrl = `https://www.youtube.com/results?search_query=${encodedSongName}`;
    window.open(youtubeUrl, "_blank");
  };

  const handleMovieClick = (movieName) => {
    const encodedMovieName = encodeQuery(movieName);
    const googleSearchUrl = `https://www.google.com/search?q=${encodedMovieName}+watch+online`;
    window.open(googleSearchUrl, "_blank");
  };

  const handleFoodClick = (foodName) => {
    const encodedFoodName = encodeQuery(foodName);
    const googleSearchUrl = `https://www.google.com/search?q=${encodedFoodName}+near+me`;
    window.open(googleSearchUrl, "_blank");
  };

  const handleWeedClick = (weedName) => {
    const encodedWeedName = encodeQuery(weedName);
    const weedMapsUrl = `https://weedmaps.com/search?filter[match]=${encodedWeedName}`;
    window.open(weedMapsUrl, "_blank");
  };

  const handleCardClick = (key, item) => {
    switch (key) {
      case 'song':
        handleSongClick(item.name);
        break;
      case 'movie':
        handleMovieClick(item.name, item.imdbId);
        break;
      case 'food':
        handleFoodClick(item.name);
        break;
      case 'weed':
        handleWeedClick(item.name);
        break;
      default:
        break;
    }
  };

  return (
    <div className="vibe-container">
      <img 
        src="https://i.imgur.com/wkmS2Pg.png" // Replace with your logo URL
        alt="Logo" 
        className="logo" 
      />
      <button onClick={randomize} className="randomize-button">
        New Vibes
      </button>
      <p className="randomize-instruction">Press Space to Randomize</p>
      <h1 className="title">Couch Potato</h1>
      <div className={`grid-container ${shake ? "shake" : ""}`}>
        {Object.entries(suggestions).map(([key, item]) => (
          <div key={key} className="grid-item" onClick={() => handleCardClick(key, item)}>
            <h2 className="item-title">Best {key}</h2>
            {key === "song" && <img src={songCover} alt={item.name} className="item-image" />}
            {key === "movie" && <img src={movieCover} alt={item.name} className="item-image" />}  {/* Display movie art */}
            {key !== "song" && key !== "movie" && <img src={item.image} alt={item.name} className="item-image" />}
            
            {/* Text above button */}
            <p className="item-text-above-button">
              {key === "song" ? `${item.artist} - ${item.song}` : item.name}
            </p>

            {key === 'song' && (
              <button onClick={() => handleSongClick(item.name)}>
                Listen on YouTube
              </button>
            )}
            {key === 'movie' && (
              <button onClick={() => handleMovieClick(item.name, item.imdbId)}>
                Watch Online
              </button>
            )}
            {key === 'food' && (
              <button onClick={() => handleFoodClick(item.name)}>
                Find Food Near Me
              </button>
            )}
            {key === 'weed' && (
              <button onClick={() => handleWeedClick(item.name)}>
                Find on Weedmaps
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

// Utility function to get random item from an array, avoiding the same item consecutively
const getRandomItem = (array, prevItem) => {
  let newItem;
  do {
    newItem = array[Math.floor(Math.random() * array.length)];
  } while (newItem === prevItem);
  return newItem;
};
